import * as cqn from './cqn'

export class Query {
  /**
  * - Fills in any binding `{param}`s with corresponding `{val}`s from given `args`.
  * - If no `args` are provided, the ones collected during parsing are used.
  */
  bind(...args: any[]): this;

  /**
  * Returns the main subject `{ref}` of the query, which refers to the entity being queried or modified.
  * - For `SELECT` and `DELETE` queries, this is the `from` clause.
  * - For `INSERT` and `UPSERT` queries, this is the `into` clause.
  * - For `UPDATE` queries, this is the `entity` clause.
  * @returns {ref:string[]} The main subject of the query.
  */
  get subject(): cqn.ref;
}
